<?php
// _erp-compat.php — tabelas derivadas de compatibilidade: schema NOVO do ERP (DSHOW_PROD, TypeORM, 2026-08-14) → shape LEGADO
// (Requisicao, Organizacao, Orcamento, Contas_A_Receber, Fornecedor…) usado pelos painéis 01/05/16. O ERP dropou as tabelas
// legadas em 19–20/08/2026. Cada constante é uma tabela derivada (SEM alias): use `FROM ' . ERP_V_REQUISICAO . ' r`.
// Mapeamentos: status requisição PENDENTE→1304 · CONVERTIDO/PARCIALMENTE_PAGO→1305 · PAGO→1306 · CANCELADO/CONTAS_CANCELADAS→1308;
// orçamento GANHO→3 · PERDIDO→4 · EM_ANDAMENTO→1 · REPROVADO→2; parcela EM_ABERTO/PARCIAL/VENCIDO→Id_Situacao 1; fornecedor ATUALIZADO→'Ativo'.
// Ativo/Flag_Ativo mantêm a convenção legada (-1 = ativo). Linhas deleted=1 do ERP não entram. Gerado por scripts/… compat-views.py em 2026-09-16.
if (!defined('ERP_V_REQUISICAO')) {
    define('ERP_V_REQUISICAO', "(SELECT r.id AS Id_Requisicao, r.descricao AS Descricao_Requisicao, (SELECT COALESCE(SUM(i.quantidade),0) FROM fin_requisicao_pagamento_item i WHERE i.id_requisicao=r.id AND i.deleted=0) AS Qtd, r.total AS Total, CASE r.status WHEN 'PENDENTE' THEN 1304 WHEN 'CONVERTIDO' THEN 1305 WHEN 'PARCIALMENTE_PAGO' THEN 1305 WHEN 'PAGO' THEN 1306 ELSE 1308 END AS Id_Situacao, CASE r.status WHEN 'PENDENTE' THEN 'Pendente Lançamento' WHEN 'CONVERTIDO' THEN 'Pendente Pagamento' WHEN 'PARCIALMENTE_PAGO' THEN 'Pendente Pagamento' WHEN 'PAGO' THEN 'Pago' ELSE 'Cancelado' END AS Situacao, (SELECT MIN(rcc.id_centro_custo) FROM fin_requisicao_pagamento_centro_custo rcc WHERE rcc.id_requisicao_pagamento=r.id) AS Id_Centro_Custo, (SELECT cc.nome FROM fin_requisicao_pagamento_centro_custo rcc JOIN fin_centro_custo cc ON cc.id=rcc.id_centro_custo WHERE rcc.id_requisicao_pagamento=r.id ORDER BY rcc.id_centro_custo LIMIT 1) AS Centro_De_Custo, r.id_fornecedor AS Id_Fornecedor, (SELECT COALESCE(NULLIF(fo.nome_fantasia,''), NULLIF(fo.razao_social,''), fp.nome) FROM ent_fornecedor f JOIN ent_entidade fe ON fe.id=f.id_entidade LEFT JOIN ent_organizacao fo ON fo.id_entidade=fe.id AND fo.deleted=0 LEFT JOIN ent_pessoa fp ON fp.id_entidade=fe.id AND fp.deleted=0 WHERE f.id=r.id_fornecedor LIMIT 1) AS Fornecedor, (SELECT COALESCE(NULLIF(co.nome_fantasia,''), NULLIF(co.apelido,''), NULLIF(co.razao_social,''), cp.nome) FROM ent_cliente c JOIN ent_entidade ce ON ce.id=c.id_entidade LEFT JOIN ent_organizacao co ON co.id_entidade=ce.id AND co.deleted=0 LEFT JOIN ent_pessoa cp ON cp.id_entidade=ce.id AND cp.deleted=0 WHERE c.id=COALESCE((SELECT ro.id_cliente FROM fin_requisicao_pagamento_orcamento ro WHERE ro.id_requisicao_pagamento=r.id LIMIT 1),(SELECT rr.id_cliente FROM fin_requisicao_pagamento_reembolso rr WHERE rr.id_requisicao_pagamento=r.id LIMIT 1)) LIMIT 1) AS Cliente, CRC32((SELECT i.categoria FROM fin_requisicao_pagamento_item i WHERE i.id_requisicao=r.id AND i.deleted=0 AND i.categoria IS NOT NULL AND i.categoria<>'' ORDER BY i.id LIMIT 1)) AS Categoria, (SELECT i.categoria FROM fin_requisicao_pagamento_item i WHERE i.id_requisicao=r.id AND i.deleted=0 AND i.categoria IS NOT NULL AND i.categoria<>'' ORDER BY i.id LIMIT 1) AS Descricao_Categoria, (r.tipo='REEMBOLSO') AS Reembolso, CASE WHEN r.tipo='REEMBOLSO' THEN r.total ELSE 0 END AS Valor_Reembolso, CASE WHEN r.tipo='REEMBOLSO' THEN (SELECT COALESCE(NULLIF(fo.nome_fantasia,''), NULLIF(fo.razao_social,''), fp.nome) FROM ent_fornecedor f JOIN ent_entidade fe ON fe.id=f.id_entidade LEFT JOIN ent_organizacao fo ON fo.id_entidade=fe.id AND fo.deleted=0 LEFT JOIN ent_pessoa fp ON fp.id_entidade=fe.id AND fp.deleted=0 WHERE f.id=r.id_fornecedor LIMIT 1) END AS Beneficiario_Reembolso, (SELECT u.nome FROM sys_usuario u WHERE u.id=r.created_by) AS Criador, DATE(r.created_at) AS Data_Requisicao, r.created_at AS Data_Criacao, r.data_prevista_pagamento AS Data_Prev_Pgto, CONCAT_WS(' · ', r.tipo, r.meio_pagamento, r.forma_pagamento) AS Observacao FROM fin_requisicao_pagamento r WHERE r.deleted=0)");
    define('ERP_V_REQUISICAO_ITEM', "(SELECT i.id AS Id, i.id_requisicao AS Id_Requisicao, COALESCE(NULLIF(i.descricao,''), i.categoria) AS Descricao_Livre, i.quantidade AS Quantidade, i.valor_unitario AS Valor_Unitario, i.subtotal AS Subtotal, NULL AS Tipo_Un, NULL AS Fornecedor, (SELECT u.nome FROM sys_usuario u WHERE u.id=i.created_by) AS Criador, i.created_at AS Data_Criacao FROM fin_requisicao_pagamento_item i WHERE i.deleted=0)");
    define('ERP_V_REQUISICAO_MIDIA', "(SELECT a.id AS Id, a.id_requisicao AS Id_Requisicao, a.tipo_arquivo AS Tipo, a.chave_s3 AS Url, a.nome_arquivo AS Nome_arquivo, a.tamanho_bytes AS Tamanho_arquivo, NULL AS Descricao, a.created_at AS Data_criacao FROM fin_requisicao_pagamento_anexo a WHERE a.deleted=0)");
    define('ERP_V_ORGANIZACAO', "(SELECT c.id AS Id_Organizacao, COALESCE(NULLIF(o.nome_fantasia,''), NULLIF(o.apelido,''), o.razao_social) AS Nome_Empresa, o.razao_social AS Razao_Social, o.cnpj AS Cnpj, CASE WHEN e.ativo=1 THEN -1 ELSE 0 END AS Flag_Ativo, (SELECT s.cidade FROM shr_endereco s WHERE s.id_entidade=e.id AND s.deleted=0 ORDER BY s.padrao DESC, s.id LIMIT 1) AS Municipio_Endereco, (SELECT s.uf FROM shr_endereco s WHERE s.id_entidade=e.id AND s.deleted=0 ORDER BY s.padrao DESC, s.id LIMIT 1) AS Uf_Endereco, (SELECT COALESCE(SUM(x.total),0) FROM orc_orcamento x WHERE x.id_cliente=c.id AND x.deleted=0 AND x.status='GANHO') AS Receita_Gerada, (SELECT COUNT(*) FROM orc_orcamento x WHERE x.id_cliente=c.id AND x.deleted=0 AND x.status='GANHO') AS Qtd_Orcs_Ganhos, (SELECT COUNT(*) FROM orc_orcamento x WHERE x.id_cliente=c.id AND x.deleted=0 AND x.status='PERDIDO') AS Qtd_Orcs_Perdidos, (SELECT DATE(MAX(x.created_at)) FROM orc_orcamento x WHERE x.id_cliente=c.id AND x.deleted=0) AS Ultimo_Contato, c.created_at AS Data_Criacao FROM ent_cliente c JOIN ent_entidade e ON e.id=c.id_entidade AND e.deleted=0 AND e.tipo='PJ' JOIN ent_organizacao o ON o.id_entidade=e.id AND o.deleted=0 WHERE c.deleted=0)");
    define('ERP_V_PESSOA', "(SELECT p.id AS Id_Pessoa, CASE WHEN e.ativo=1 THEN -1 ELSE 0 END AS Ativo FROM ent_pessoa p JOIN ent_entidade e ON e.id=p.id_entidade AND e.deleted=0 WHERE p.deleted=0)");
    define('ERP_V_ORCAMENTO', "(SELECT x.id AS Id_Orc, x.id_cliente AS Id_Organizacao, CASE x.status WHEN 'GANHO' THEN 3 WHEN 'PERDIDO' THEN 4 WHEN 'EM_ANDAMENTO' THEN 1 ELSE 2 END AS Id_Status, x.tipo_negocio AS Tipo_Negocio, x.total AS Valor_Final, (SELECT u.nome FROM sys_usuario u WHERE u.id=x.id_vendedor) AS Nome_Vendedor, x.data_ganho AS Data_Ganho, x.created_at AS Data_Criacao, x.motivo_perda AS Motivo_Perda, x.data_perda AS Data_Perda FROM orc_orcamento x WHERE x.deleted=0)");
    define('ERP_V_CONTAS_A_RECEBER', "(SELECT p.id AS Id, cr.id_cliente AS Id_Organizacao, p.valor AS Valor, p.vencimento AS Vencimento, CASE WHEN p.status IN ('EM_ABERTO','PARCIAL','VENCIDO') THEN 1 WHEN p.status IN ('RECEBIDO','RECUPERADO') THEN 2 ELSE 3 END AS Id_Situacao, p.status AS Situacao FROM fin_conta_receber_parcela p JOIN fin_conta_receber cr ON cr.id=p.id_conta_receber AND cr.deleted=0 WHERE p.deleted=0)");
    define('ERP_V_FORNECEDOR', "(SELECT f.id AS Id_Fornecedor, e.tipo AS Tipo, o.cnpj AS Cnpj, p.cpf AS Cpf, COALESCE(p.nome, o.razao_social) AS Nome, o.razao_social AS Nome_Empresa, NULLIF(o.nome_fantasia,'') AS Fantasia, CASE WHEN e.ativo=1 THEN -1 ELSE 0 END AS Ativo, (SELECT COUNT(*) FROM fin_requisicao_pagamento r WHERE r.id_fornecedor=f.id AND r.deleted=0) AS Qtd_Requisicoes, (SELECT COALESCE(SUM(r.total),0) FROM fin_requisicao_pagamento r WHERE r.id_fornecedor=f.id AND r.deleted=0 AND r.status IN ('PAGO','PARCIALMENTE_PAGO')) AS Total_Pago, CASE f.status WHEN 'ATUALIZADO' THEN 'Ativo' ELSE 'Desatualizado' END AS Status, (SELECT ct.chave FROM ent_fornecedor_email fe JOIN shr_contato ct ON ct.id=fe.id_contato AND ct.deleted=0 WHERE fe.id_fornecedor=f.id ORDER BY ct.padrao DESC, ct.id LIMIT 1) AS Email, (SELECT ct.chave FROM ent_fornecedor_telefone ft JOIN shr_contato ct ON ct.id=ft.id_contato AND ct.deleted=0 WHERE ft.id_fornecedor=f.id ORDER BY ct.padrao DESC, ct.id LIMIT 1) AS Telefone, NULL AS Celular, f.tipo_relacao AS Tipo_Relacao, ad.logradouro AS Endereco_Logradouro, ad.numero AS Endereco_Numero, ad.bairro AS Endereco_Bairro, ad.cidade AS Endereco_Municipio, ad.uf AS Endereco_Uf, ad.cep AS Endereco_Cep, f.created_at AS Data_Criacao, f.updated_at AS Ultima_Modificacao FROM ent_fornecedor f JOIN ent_entidade e ON e.id=f.id_entidade LEFT JOIN ent_organizacao o ON o.id_entidade=e.id AND o.deleted=0 LEFT JOIN ent_pessoa p ON p.id_entidade=e.id AND p.deleted=0 LEFT JOIN shr_endereco ad ON ad.id=(SELECT s.id FROM shr_endereco s WHERE s.id_entidade=e.id AND s.deleted=0 ORDER BY s.padrao DESC, s.id LIMIT 1) WHERE f.deleted=0)");
    define('ERP_V_FORNECEDOR_CONTA_BANCARIA', "(SELECT b.id AS Id_Conta, b.id_fornecedor AS Id_Fornecedor, NULL AS Cpf_Cnpj, b.beneficiario AS Nome_Titular, b.agencia AS Agencia, CONCAT_WS(' ', b.banco, b.numero_conta) AS Conta, (SELECT px.chave_pix FROM fin_chave_pix px WHERE px.id_fornecedor=b.id_fornecedor AND px.deleted=0 AND px.ativo=1 ORDER BY px.id LIMIT 1) AS Pix FROM fin_dado_bancario b WHERE b.deleted=0 AND b.id_fornecedor IS NOT NULL UNION ALL SELECT px.id+1000000, px.id_fornecedor, NULL, NULL, NULL, NULL, px.chave_pix FROM fin_chave_pix px WHERE px.deleted=0 AND px.ativo=1 AND px.id_fornecedor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM fin_dado_bancario b WHERE b.id_fornecedor=px.id_fornecedor AND b.deleted=0))");
}

